
.station-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.3rem;
  width: 100%;
  padding: 1.25rem 1rem;
  border-radius: 1.1rem;
  border: 2px solid var(--farm-wood);
  background: var(--farm-cream);
  text-align: center;
}

.station-card:disabled {
  cursor: not-allowed;
  opacity: 0.6;
}

.station-card__icon {
  font-size: 2.5rem;
  line-height: 1;
}

.station-card__name {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--farm-text-dark);
}

.station-card__progress {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--farm-text-muted);
}

.station-card__status {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--farm-text-muted);
}

.station-card__hint {
  font-size: 0.68rem;
  color: var(--farm-wood-dark);
}

.station-card--accessible {
  border-color: var(--farm-accent-dark);
}

.station-card--accessible .station-card__status {
  color: var(--farm-accent-dark);
}

.station-card--completed {
  border-color: #f2b134;
  background: var(--farm-cream-dark);
}

.station-card--completed .station-card__status {
  color: #b3841f;
}
